// Rune Weaver Dashboard — Persona avatar rendering, avatar-state resolution, and the
// shared persona-signals store.
//
// Purpose: one home for the three persona surfaces both identity consumers need: the
// `PersonaAvatar` img (the Wisp sprite PNGs generated by scripts/generate_persona_avatars.py
// into Web/public/avatars at 32/64/256), the pure `resolveAvatarState` priority that maps
// activity signals onto the four sprite states, and a small module-level signals store
// through which persona identity and agent liveness travel between the components that
// own them (Settings publishes the saved persona; ChatView publishes activity and
// working state; TopNav publishes the attention badges it already receives) and the
// components that render them (the top-nav profile block and the chat header).
// Scope: rendering and client-owned liveness signals only. Persona persistence stays
// on the settings save path, and the sprite bytes stay the deterministic output of the
// generator script; this module never fabricates an identity, invents an asset, or
// turns drifted server data into a signal.
// Architectural role: keeps identity fail-closed in exactly one render path. Unknown
// accent keys fall back to the violet colorway, unknown state keys to idle, and an
// image that cannot load falls back to the brand `RuneGlyph` — so server data can never
// throw here and the user can never see a broken image. The store mirrors the shared
// `useRunningRuns` external-store idiom (module state, listener set, `useSyncExternalStore`,
// test-only reset) rather than prop-drilling identity through every screen.

import { useEffect, useState, useSyncExternalStore } from "react";
import {
  DEFAULT_PERSONA_AVATAR,
  PERSONA_AVATAR_COLORS,
  normalizePersonaAvatarColor,
  type PersonaData,
} from "../api";
import { RuneGlyph } from "./icons";

// Sprite states render one body with eyes and accents only differing; the closed
// set is fixed by the asset generator, so a drifted server or store value must
// degrade to `idle` instead of pointing at a PNG that does not exist.
export type AvatarState = "idle" | "sleeping" | "working" | "attention";

const AVATAR_STATES: readonly AvatarState[] = [
  "idle",
  "sleeping",
  "working",
  "attention",
];

// Minutes of silence before the Wisp dims to sleeping. This is a deliberately
// fixed cosmetic threshold, not configuration: a config key for an idle timer
// would invite settings sprawl for a value nobody tunes, so one documented
// constant owns it on every surface and the priority test pins the boundary.
export const AVATAR_SLEEP_MS = 10 * 60 * 1000;

// Cadence and duration of the idle blink. The blink is a CSS lid drawn over the
// idle frame for a brief window every few seconds — it never swaps the image to
// the sleeping asset, because that frame carries closed eyes plus Z marks and a
// dimmed core that would read as a state change every few seconds. Keeping the
// src pinned to idle preserves the four-state contract (idle blinks, sleeping
// sleeps) while the overlay supplies the closed-eyes read. Both values are
// cosmetic and intentionally untuned.
export const BLINK_INTERVAL_MS = 4000;
export const BLINK_CLOSED_MS = 150;

// Body-mid gradient stop per colorway, mirroring the generator's fixed palette.
// The lid sits where the open eyes are (upper body, near the mid stop), so
// painting it in the local body tone hides the glow without dimming the core
// or borrowing the sleeping frame's Z marks. Approximate is deliberate: the lid
// is visible for one blink window and only needs to read as closed lids, not
// to reproduce the gradient exactly.
const BLINK_LID_COLORS: Record<string, string> = {
  violet: "#8b5cf6",
  cyan: "#22d3ee",
  emerald: "#34d399",
  rose: "#fb7185",
};

// The three raster sizes the generator emits per colorway-state pair. The srcSet
// ships all three so a 16px trigger reads the 32px sheet and a 64px picker cell
// reads 1:1 instead of being downsampled from 256 by the browser.
export const AVATAR_SIZES = [32, 64, 256] as const;

export interface AvatarStateInput {
  // Attention wins unconditionally: a pending approval or a goal parked on owner
  // input is the one thing the owner must not miss, so it outranks every mood.
  hasAttention?: boolean;
  // Any in-flight run — chat, scheduler, goal, index, or fan-out — means the
  // agent is working regardless of the idle clock.
  isWorking?: boolean;
  // Epoch ms of the last observed turn end or run frame. Zero or a non-finite
  // value means "no activity observed yet" and reads as idle, never sleeping:
  // a freshly loaded dashboard has no elapsed-time basis for a sleep claim.
  lastActivityAtMs?: number | null;
  // Caller-supplied clock so the priority is pure and the 10-minute boundary is
  // unit-testable without fake timers reaching into this module.
  nowMs?: number;
}

// Pure avatar-state priority: attention > working > sleeping > idle. Kept free of
// React and of store reads so the shell can resolve one state for every surface and
// the matrix stays under unit test; the timers that re-evaluate the sleeping rule
// live in `useResolvedAvatarState`, not here.
export function resolveAvatarState(input: AvatarStateInput): AvatarState {
  if (input.hasAttention === true) return "attention";
  if (input.isWorking === true) return "working";
  const lastActivityAtMs = input.lastActivityAtMs;
  const nowMs = input.nowMs ?? Date.now();
  if (
    typeof lastActivityAtMs === "number" &&
    Number.isFinite(lastActivityAtMs) &&
    lastActivityAtMs > 0 &&
    Number.isFinite(nowMs) &&
    nowMs - lastActivityAtMs >= AVATAR_SLEEP_MS
  ) {
    return "sleeping";
  }
  return "idle";
}

// Builds the public asset path for one sprite frame. The bundle serves
// `Web/public` at the origin root, so absolute paths resolve under both the
// engine-served dist and the Vite dev server; keeping the template in one
// function prevents a consumer from inventing a fifth spelling.
export function personaAvatarFramePath(
  color: string,
  state: string,
  size: number,
): string {
  return `/avatars/wisp-${color}-${state}-${size}.png`;
}

function normalizeAvatarState(value: string | null | undefined): AvatarState {
  const candidate = (value ?? "").trim().toLowerCase();
  return (AVATAR_STATES as readonly string[]).includes(candidate)
    ? (candidate as AvatarState)
    : "idle";
}

function normalizeAvatarColor(value: string | null | undefined): string {
  const candidate = normalizePersonaAvatarColor(value);
  return (PERSONA_AVATAR_COLORS as readonly string[]).includes(candidate)
    ? candidate
    : DEFAULT_PERSONA_AVATAR;
}

// ---------------------------------------------------------------------------
// Shared persona signals store
// ---------------------------------------------------------------------------

// Client-owned persona signals. Each field has exactly one publisher so the
// surfaces never fight over state:
//   persona          — SettingsManager publishes on every settings load and on a
//                      persona save, so a rename mirrors into the profile block
//                      and the chat header without waiting for a reload.
//   attention        — TopNav publishes from the global approvals/goals badges it
//                      already receives from the shell (they live nowhere else).
//   working/activity — ChatView is the single writer: it sees every turn terminal
//                      and every WS run frame, and republishes the derived working
//                      flag plus the last-activity instant. No new transport rides
//                      here; every value is a client-side mirror of traffic the
//                      dashboard already receives.
export interface PersonaSignals {
  persona: PersonaData | null;
  // Distinguishes "never fetched" from "fetched, and the engine carries no
  // persona": the mount fetch skips itself once a load has answered, while
  // consumers still render the stock identity either way.
  personaLoaded: boolean;
  attention: boolean;
  working: boolean;
  // Epoch ms; 0 means no turn end or run frame has been observed yet.
  lastActivityAtMs: number;
}

const EMPTY_SIGNALS: PersonaSignals = Object.freeze({
  persona: null,
  personaLoaded: false,
  attention: false,
  working: false,
  lastActivityAtMs: 0,
});

// Snapshot reference only changes on a real publish so React's store reads stay
// stable between writes, mirroring the shared-runs idiom: readers never tear and
// an identical write never re-renders the whole shell.
let signals: PersonaSignals = Object.freeze({ ...EMPTY_SIGNALS });
const signalsListeners = new Set<() => void>();

function publishSignals(next: Partial<PersonaSignals>): void {
  let changed = false;
  for (const key of Object.keys(next) as Array<keyof PersonaSignals>) {
    if (signals[key] !== next[key]) {
      changed = true;
      break;
    }
  }
  if (!changed) return;
  signals = Object.freeze({ ...signals, ...next });
  for (const listener of [...signalsListeners]) {
    try {
      listener();
    } catch {
      // One throwing subscriber never starves the rest.
    }
  }
}

function subscribePersonaSignals(listener: () => void): () => void {
  signalsListeners.add(listener);
  return () => {
    signalsListeners.delete(listener);
  };
}

function getPersonaSignalsSnapshot(): PersonaSignals {
  return signals;
}

// Direct non-React read of the current snapshot. The store hands out frozen
// objects, so callers outside a render cycle (one-shot mount probes and tests
// asserting the single-writer contract) can read it without subscribing.
export function peekPersonaSignals(): PersonaSignals {
  return signals;
}

function getPersonaSignalsServerSnapshot(): PersonaSignals {
  return EMPTY_SIGNALS;
}

export function usePersonaSignals(): PersonaSignals {
  return useSyncExternalStore(
    subscribePersonaSignals,
    getPersonaSignalsSnapshot,
    getPersonaSignalsServerSnapshot,
  );
}

// Records the persona carried by a settings payload. Undefined normalizes to null
// (an engine predating `[persona]` keeps the stock identity), and the loaded flag
// is set even on a persona-less answer so the one-shot mount fetch never repeats.
export function publishPersonaFromSettings(
  persona: PersonaData | null | undefined,
): void {
  publishSignals({
    persona: persona ?? null,
    personaLoaded: true,
  });
}

export function publishAgentAttention(attention: boolean): void {
  publishSignals({ attention });
}

export function publishAgentWorking(working: boolean): void {
  publishSignals({ working });
}

// Monotonic by construction: a late-arriving stale frame must never rewind the
// idle clock, because rewinding would keep a sleeping Wisp awake after the
// silence it claims to measure. Non-positive or non-finite input is dropped.
export function publishAgentActivity(activityMs: number): void {
  if (!Number.isFinite(activityMs) || activityMs <= 0) return;
  if (activityMs <= signals.lastActivityAtMs) return;
  publishSignals({ lastActivityAtMs: activityMs });
}

// Test-only reset that detaches the module singleton between suites, mirroring
// `resetSharedRunsForTesting`. Gated to the test bundle so production can never
// wipe live signals.
export function resetPersonaSignalsForTesting(): void {
  if (import.meta.env.MODE !== "test") return;
  signals = Object.freeze({ ...EMPTY_SIGNALS });
  signalsListeners.clear();
}

// Largest delay `setTimeout` can actually represent: both Node and the HTML
// timer spec treat anything above the signed 32-bit ceiling as an overflow —
// Node warns and fires after 1 ms, browsers refuse the wake silently.
const MAX_TIMER_DELAY_MS = 2_147_483_647;

// Resolves the sprite state from the shared signals for one identity surface.
// The pure priority is re-evaluated on every relevant store change; the only
// extra machinery is a timer that wakes the component when the idle clock
// crosses `AVATAR_SLEEP_MS`, so idle→sleeping lands without any polling.
// Attention and working short-circuit sleeping, so no timer is armed while
// either is active.
//
// The wake delay is always re-derived from the absolute sleep deadline against
// the CURRENT `Date.now()` and clamped to `MAX_TIMER_DELAY_MS`, so an epoch
// scale timestamp can never be passed as a duration. On a coherent clock the
// clamp is inert — the deadline is at most `AVATAR_SLEEP_MS` away, so one
// timer still lands exactly on the threshold. Only when two clock sources
// disagree (a test clock parked at epoch beside a store value written by a
// real `Date.now()`) does the effect re-arm on each fire until the deadline
// genuinely passes, keeping the idle→sleeping landing intact in that
// pathological case instead of overflowing the timer into an immediate wake.
export function useResolvedAvatarState(): AvatarState {
  const { attention, working, lastActivityAtMs } = usePersonaSignals();
  const [nowMs, setNowMs] = useState(() => Date.now());
  useEffect(() => {
    if (attention || working) return;
    if (lastActivityAtMs <= 0) return;
    const sleepDeadlineAtMs = lastActivityAtMs + AVATAR_SLEEP_MS;
    let timer: ReturnType<typeof setTimeout> | null = null;
    const arm = () => {
      const remaining = sleepDeadlineAtMs - Date.now();
      if (remaining <= 0) {
        // The store moved (e.g. working cleared) past the threshold while no
        // timer was armed, so re-evaluate now instead of waiting for the next
        // unrelated render.
        setNowMs(Date.now());
        return;
      }
      timer = setTimeout(arm, Math.min(remaining, MAX_TIMER_DELAY_MS));
    };
    arm();
    return () => {
      if (timer !== null) clearTimeout(timer);
    };
  }, [attention, working, lastActivityAtMs]);
  return resolveAvatarState({
    hasAttention: attention,
    isWorking: working,
    lastActivityAtMs,
    nowMs,
  });
}

interface PersonaAvatarProps {
  // Raw server accent (or a picker draft); validated inside, never here — callers
  // pass what they hold and the fallback rule stays single-sourced.
  color?: string | null;
  // Raw state token; unknown values render the idle frame.
  state?: string | null;
  // Rendered size in px; srcSet always ships the full 32/64/256 triple.
  size?: number;
  className?: string;
  // Accessible name; surfaces that pair the avatar with the visible persona name
  // pass an empty string so the image stays decorative and screen readers do not
  // announce the identity twice.
  label?: string;
  dataTestId?: string;
  // Idle blink opt-out. The live identity surfaces blink because a resting
  // assistant reads as alive; the settings picker renders static frames — a
  // blinking swatch would look like a state change it cannot acknowledge.
  blink?: boolean;
}

// The Wisp avatar itself. Idle blinks by drawing a short-lived CSS lid over the
// idle frame (closed eyes without the sleeping frame's Z marks or dimmed core),
// and the blink timer pauses while the tab is hidden: a background tab costs
// nothing to animate, but keeping it ticking would wake a timer on a page nobody
// is looking at, so visibility owns the interval entirely. Sleeping slow-floats
// and working gently pulses via the stylesheet; attention stays static because
// the amber ring is already the signal and motion would cheapen it.
export function PersonaAvatar({
  color,
  state,
  size = 32,
  className = "",
  label = "Assistant avatar",
  dataTestId,
  blink = true,
}: PersonaAvatarProps) {
  const avatarColor = normalizeAvatarColor(color);
  const avatarState = normalizeAvatarState(state);
  // A failed frame load latches the glyph fallback, but the latch clears with
  // the frame: a different colorway or state may resolve fine, and a persistent
  // glyph for the whole session would hide a recovery the browser already made.
  const [imageFailed, setImageFailed] = useState(false);
  useEffect(() => {
    setImageFailed(false);
  }, [avatarColor, avatarState]);

  const [blinkClosed, setBlinkClosed] = useState(false);
  const blinkActive = avatarState === "idle" && !imageFailed && blink;
  useEffect(() => {
    if (!blinkActive) {
      setBlinkClosed(false);
      return;
    }
    let interval: ReturnType<typeof setInterval> | null = null;
    let closedTimer: ReturnType<typeof setTimeout> | null = null;
    const blinkOnce = () => {
      setBlinkClosed(true);
      closedTimer = setTimeout(() => {
        closedTimer = null;
        setBlinkClosed(false);
      }, BLINK_CLOSED_MS);
    };
    const start = () => {
      if (interval === null) interval = setInterval(blinkOnce, BLINK_INTERVAL_MS);
    };
    const stop = () => {
      if (interval !== null) {
        clearInterval(interval);
        interval = null;
      }
      if (closedTimer !== null) {
        clearTimeout(closedTimer);
        closedTimer = null;
      }
      // A hidden tab that closed mid-blink must never re-show a half-blinked
      // Wisp when the owner returns.
      setBlinkClosed(false);
    };
    const onVisibility = () => {
      if (typeof document !== "undefined" && document.hidden) stop();
      else start();
    };
    if (!(typeof document !== "undefined" && document.hidden)) start();
    document.addEventListener("visibilitychange", onVisibility);
    return () => {
      document.removeEventListener("visibilitychange", onVisibility);
      stop();
    };
  }, [blinkActive]);

  if (imageFailed) {
    // The brand rune mark is the definitive no-broken-image fallback. It is
    // wrapped (rather than given the test id directly) because the icon's
    // props type is a plain SVG spread. A decorative instance carries
    // `aria-hidden` instead of an empty accessible name.
    return (
      <span
        className={`persona-avatar persona-avatar-fallback${className ? ` ${className}` : ""}`}
        data-testid={dataTestId}
        role={label ? "img" : undefined}
        aria-label={label || undefined}
        aria-hidden={label ? undefined : true}
      >
        <RuneGlyph size={size} className="rune-glyph-icon" />
      </span>
    );
  }

  // The blink never swaps the frame: the src and the state class always name
  // the resolved avatar state, so a blink can never flash the sleeping PNG's Z
  // marks, dimmed core, or float animation, nor masquerade as sleeping in the
  // DOM. The closed-eyes read comes solely from the lid overlay below.
  const shownState: AvatarState = avatarState;
  const isBlinking = avatarState === "idle" && blinkClosed;
  const srcSet = AVATAR_SIZES.map(
    (px) => `${personaAvatarFramePath(avatarColor, shownState, px)} ${px}w`,
  ).join(", ");
  const imgClassName = `persona-avatar persona-avatar--${shownState}${isBlinking ? " persona-avatar--blinking" : ""}${className ? ` ${className}` : ""}`;
  const img = (
    <img
      src={personaAvatarFramePath(avatarColor, shownState, 64)}
      srcSet={srcSet}
      sizes={`${size}px`}
      width={size}
      height={size}
      alt={label}
      draggable={false}
      data-testid={dataTestId}
      className={imgClassName}
      onError={() => setImageFailed(true)}
    />
  );
  if (!isBlinking) return img;
  // Closed-eyes lid for the 150 ms blink window. The wrapper pins the overlay
  // geometry to the rendered size with inline styles (no stylesheet or asset
  // change), and the lid covers the eye band in the local body tone: the open
  // glow hides, the core stays bright, and no Z mark ever appears — the three
  // properties that keep a blink visually distinct from sleeping.
  return (
    <span
      className="persona-avatar-blink"
      style={{
        position: "relative",
        display: "inline-block",
        width: size,
        height: size,
        lineHeight: 0,
        verticalAlign: "middle",
      }}
    >
      {img}
      <span
        aria-hidden="true"
        className="persona-avatar-blink-lid"
        style={{
          position: "absolute",
          left: "30%",
          right: "30%",
          top: "37%",
          height: "11%",
          background: BLINK_LID_COLORS[avatarColor] ?? BLINK_LID_COLORS.violet,
          borderRadius: "9999px",
        }}
      />
    </span>
  );
}
